r={}
for i,o in x.items():
 status,reason,gap,evidence=notes[i];a=o['source_url'].rsplit('/',1)[-1]
 src=[]
 for p in sorted((D/'sources').glob(a+'*.receipt.json')):
  src.append(json.loads(p.read_text()))
 r[i]={**o,'outcome':status,'review_depth':'literal corpus statement; historical ID/title screen; current source target/context and neighboring results; all historical arXiv version target contexts where versions exist; bounded live literature and proof-registry screen. Complete proof-body audits are only claimed where described in disposition.','disposition':reason,'remaining_lemmas_or_limits':gap,'evidence':evidence.split('; '),'source_receipts':src,'credit':0,'lean_endpoint':None,'root_acceptance':'not requested or obtained','novelty_clearance':'not globally established; see outputs/registry-screen.json; no exhaustive citing-work audit'}
assert set(map(int,r))==set(json.loads((D/'reservation.json').read_text())['ids']) and len(r)==20
(D/'results.json').write_text(json.dumps(r,indent=2,ensure_ascii=False)+'\n')
manifest={str(p.relative_to(D)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(D.rglob('*')) if p.is_file() and p.name not in ['artifact-manifest.json']}
(D/'outputs/artifact-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
